"""
    Returns True if the user has provided all of the required registration info

    Args:
        user (django.contrib.auth.models.User):

    Returns:
        bool: True if the user has provided all of the required registration info
    """
def is_user_info_complete(user: Any) -> object {
    return (
        hasattr(user, "profile")
        and user.profile.is_complete
        and hasattr(user, "legal_address")
        and user.legal_address.is_complete
    );
}

"""
    Converts a value triplet to boolean2 values
    From a triplet: concentration, decay, threshold
    Truth value = conc > threshold/decay
    """
def tuple_to_bool(value: Any) -> object {
    return (value[0] > (value[2] / value[1]));
}

"""Calculates hamming syndrom"""
def calculateHammingSyndrom(byte: Any) -> object {
    S0 = str(
        (
            int(byte[1])
            ^ int(byte[3])
            ^ int(byte[5])
            ^ int(byte[7])
            ^ int(byte[9])
            ^ int(byte[11])
        )
    );
    S1 = str(
        (
            int(byte[2])
            ^ int(byte[3])
            ^ int(byte[6])
            ^ int(byte[7])
            ^ int(byte[10])
            ^ int(byte[11])
        )
    );
    S2 = str(
        (int(byte[4]) ^ int(byte[5]) ^ int(byte[6]) ^ int(byte[7]) ^ int(byte[12]))
    );
    S3 = str(
        (int(byte[8]) ^ int(byte[9]) ^ int(byte[10]) ^ int(byte[11]) ^ int(byte[12]))
    );
    SX = str(
        (
            int(byte[0])
            ^ int(byte[1])
            ^ int(byte[2])
            ^ int(byte[3])
            ^ int(byte[4])
            ^ int(byte[5])
            ^ int(byte[6])
            ^ int(byte[7])
            ^ int(byte[8])
            ^ int(byte[9])
            ^ int(byte[10])
            ^ int(byte[11])
            ^ int(byte[12])
        )
    );
    S = int((S3 + S2 + S1 + S0), 2);
    return {"SX": int(SX), "S": S};
}

"""
    Get the most visibile camera's annotation.
    :param camera_data_dict: Dictionary of form:
      {
        'CAM_BACK': {'attribute_tokens': ['cb5118da1ab342aa947717dc53544259'],
          'bbox_corners': [600.8315617945755,
          426.38901275036744,
          643.6756536789582,
          476.66593163100237],
          'category_name': 'vehicle.bus.rigid',
          'filename': 'samples/CAM_BACK/n015-2018-10-02-10-50-40+0800__CAM_BACK__1538448750037525.jpg',
          'instance_token': '9cba9cd8af85487fb010652c90d845b5',
          'next': 'ef90c2e525244b7d9eeb759837cf2277',
          'num_lidar_pts': 0,
          'num_radar_pts': 0,
          'prev': '6628e81912584a72bd448a44931afb42',
          'sample_annotation_token': '06b4886e79d2435c80bd23e7ac60c618',
          'sample_data_token': '0008443755a14b3ca483f1489c767040',
          'visibility_token': '4'},
        'CAM_FRONT': ...
        ...
      }
    :return: The camera annotation with highest visibility.
    """
def get_most_visible_camera_annotation(camera_data_dict: dict) -> dict {
    best_visibility = '';
    largest_area = -1;
    best_camera_token = None;
    for camera_token in camera_data_dict {
        visibility = camera_data_dict[camera_token]['visibility_token'];
        bbox_area = camera_data_dict[camera_token]['bbox_area'];
        if (
            (visibility > best_visibility)
            or ((visibility == best_visibility) and (bbox_area > largest_area))
        ) {
            best_camera_token = camera_token;
            largest_area = bbox_area;
            best_visibility = visibility;
        }
    }
    if not best_camera_token {
        print(
            'Unable to find any good views for camera data dict: {}'.format(
                camera_data_dict
            )
        );
    }
    best_instance_data = camera_data_dict[best_camera_token];
    return best_instance_data;
}

""" Returns the ROC curve as an iterator of (x, y)-points,
        for the given list of (TP, TN, FP, FN)-tuples.
        The x-axis represents FPR = the false positive rate (1 - specificity).
        The y-axis represents TPR = the true positive rate.
    """
def roc(tests: Any = []) -> object {
    x = FPR=lambda (TP: Any, TN: Any, FP: Any, FN: Any) { (
        float(FP) / ((FP + TN) or 1)
    ); };
    y = TPR=lambda (TP: Any, TN: Any, FP: Any, FN: Any) { (
        float(TP) / ((TP + FN) or 1)
    ); };
    return sorted(([(0.0, 0.0), (1.0, 1.0)] + [(x(*m), y(*m)) for m in tests]));
}

